#nullable enable // autogenerated

using System;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Entities
{

    [AutoBuffDefinition(VanillaBuffNames.Contraption.teleporterTriggered)]
    public class TeleporterTriggeredBuff : TeleporterBuff
    {
        public TeleporterTriggeredBuff(string nsp, string name) : base(nsp, name)
        {
            IsUp = true;
            AddModifier(new NamespaceIDArrayModifier(LogicEntityProps.GRID_LAYERS, ArrayOperator.Replace, Array.Empty<NamespaceID>()));
            AddModifier(new BooleanModifier(VanillaEntityProps.AI_FROZEN, true));
        }
        protected override void OnFinished(Buff buff)
        {
            base.OnFinished(buff);
            buff.GetEntity()?.Remove();
        }
    }
}
